import { Box, Container } from "@mui/material";
import { Outlet, useLocation } from "react-router-dom";

import DashboardHeader from "../components/layout/DashboardHeader";
import DashboardSidebar from "../components/layout/DashboardSidebar";

const pageTitles: Record<string, { title: string; subtitle: string }> = {
  "/forecast": {
    title: "Coal Stockpile Forecast",
    subtitle: "AI-powered predictions with weather intelligence and scenario analysis",
  },
  "/model-performance": {
    title: "Model Performance Analytics",
    subtitle: "Real-time accuracy metrics and out-of-time validation",
  },
  "/inference": {
    title: "System Health & Monitoring",
    subtitle: "Pipeline execution, API metrics, and resource monitoring",
  },
  "/inference-monitoring": {
    title: "Inference Activity Monitor",
    subtitle: "Live inference tracking and performance analytics",
  },
};

const DashboardLayout = () => {
  const location = useLocation();
  const page = pageTitles[location.pathname] ?? {
    title: "Eskom Forecast Intelligence",
    subtitle: "Advanced Analytics Dashboard",
  };

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        bgcolor: "#0A0E27", // Deep dark background for command center feel
        backgroundImage: `
          radial-gradient(circle at 20% 50%, rgba(13, 99, 244, 0.08) 0%, transparent 50%),
          radial-gradient(circle at 80% 80%, rgba(22, 163, 74, 0.06) 0%, transparent 50%)
        `,
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Animated background grid */}
      <Box
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundImage: `
            linear-gradient(rgba(13, 99, 244, 0.03) 1px, transparent 1px),
            linear-gradient(90deg, rgba(13, 99, 244, 0.03) 1px, transparent 1px)
          `,
          backgroundSize: "50px 50px",
          opacity: 0.3,
          pointerEvents: "none",
        }}
      />

      {/* Sidebar - Enhanced with glassmorphism */}
      <DashboardSidebar />

      {/* Main Content Area */}
      <Box
        sx={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          minWidth: 0,
          position: "relative",
        }}
      >
        {/* Header - Floating glass card */}
        <Box
          sx={{
            position: "sticky",
            top: 0,
            zIndex: 1000,
            backdropFilter: "blur(20px)",
            backgroundColor: "rgba(10, 14, 39, 0.8)",
            borderBottom: "1px solid rgba(255, 255, 255, 0.05)",
            boxShadow: "0 8px 32px rgba(0, 0, 0, 0.3)",
          }}
        >
          <Container
            maxWidth={false}
            sx={{
              px: { xs: 2, sm: 3, lg: 4 },
              py: 2.5,
            }}
          >
            <Box>
              <Box
                sx={{
                  fontSize: "1.75rem",
                  fontWeight: 800,
                  background: "linear-gradient(135deg, #fff 0%, rgba(255,255,255,0.7) 100%)",
                  backgroundClip: "text",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  mb: 0.5,
                  letterSpacing: "-0.02em",
                }}
              >
                {page.title}
              </Box>
              <Box
                sx={{
                  fontSize: "0.875rem",
                  color: "rgba(255, 255, 255, 0.5)",
                  fontWeight: 500,
                }}
              >
                {page.subtitle}
              </Box>
            </Box>
          </Container>
        </Box>

        {/* Page Content - Elevated cards on dark background */}
        <Box
          component="main"
          sx={{
            flex: 1,
            overflow: "auto",
            py: 4,
          }}
        >
          <Container
            maxWidth={false}
            sx={{
              px: { xs: 2, sm: 3, lg: 4 },
            }}
          >
            <Outlet />
          </Container>
        </Box>
      </Box>
    </Box>
  );
};

export default DashboardLayout;
